"""r45 内容块 1：book.tex 薄条增写（生理/历史/性病 HIV/衣着）"""
C = {}

C["b539"] = r"""这一现象有扎实的量化支撑：2018 年发表于《性行为档案》的大样本调查显示，异性恋关系中女性每次性行为达到高潮的比例约为 65\%，而男性约为 95\%；值得注意的是，女同性伴侣中女性的高潮率显著更高——这说明"差距"不是女性生理的缺陷，而是普遍性行为脚本（重插入、轻阴蒂刺激、时间不足、缺少沟通）的产物。把高潮差距当作公共议题来讨论，其价值在于促使伴侣双方把"她是否满足"当作与"他是否持久"同等级别的问题来对待——愉悦的平等不是运气，是可以学习和练习的技巧。"""

C["b616"] = r"""决定方向的是一条基因信号链：约在胚胎第 6 周，Y 染色体上的 SRY 基因如果成功表达，未分化的性腺便朝睾丸方向发育；没有这条信号，性腺则按"默认路径"发育为卵巢。随后睾丸分泌的三种物质各司其职——睾酮促使男性内生殖器形成，双氢睾酮塑造外生殖器，抗副中肾管激素"拆除"女性管道的雏形。这条链条的任何一环出偏差（基因缺失、受体异常、酶缺乏），都可能导致性腺、染色体与外生殖器不完全一致，即间性状态——这也是理解间性人群时最重要的生理背景。"""

C["b628"] = r"""一个常被忽略的事实是：阴茎与阴蒂是同源器官——两者都由胚胎期的生殖结节发育而来，只是在此后是否接受双氢睾酮的作用而走向不同形态。这解释了两者结构上的高度相似：阴蒂同样有海绵体、同样在性唤起时充血勃起，其头部密布的神经末梢数量（约 8000 个）甚至超过阴茎头部。理解这种同源关系有两层意义：其一，"阴蒂刺激不是前戏的配菜，而是与阴茎刺激等价的性表达"；其二，它从胚胎学上说明男女性系统是同一张设计图的两个实现版本，差异是程度的，而非本质的。"""

C["b652"] = r"""自慰不是后天学来的"坏习惯"，而是刻在发育程序里的本能行为：产房超声曾记录到胎儿在子宫内抓握生殖器的自慰样动作，幼童在探索身体时触碰生殖器带来愉悦也是普遍现象，多种灵长类动物同样有自慰行为。这说明自慰首先是神经系统正常发育的标志之一，是身体对"愉悦可以由自己产生"的早期学习。把它从道德叙事中剥离出来、按平常心对待，恰恰是健全性观念的第一步——羞耻感本身造成的心理负担，远比这个行为更伤人。"""

C["b1134"] = r"""从生理机制看，梦交与快速眼动睡眠期（REM）的生理唤起直接相关——此期血流普遍集中于盆腔，男性伴勃起、女性伴阴部充血，遇上相关梦境便可能完整触发性反应。它的频率随年龄与性生活状态波动：青年期、性生活稀疏期更常见，均属正常。历史上"梦遗伤精""一滴精十滴血"的说法并无科学依据，精液的生成是持续性的，梦遗的"损失"与正常射精没有区别。需要留意的只有两种情形：因频繁遗精影响睡眠与日间状态，或伴随明显的焦虑抑郁情绪——前者可就诊排查生殖道炎症，后者更适合从压力与心理层面入手，而非服用"固精"补品。"""

C["b1549"] = r"""衣着在亲密关系中的力量有两层：一层是给对方看的"视觉前戏"——蕾丝、丝质、剪裁对特定部位的强调，都是直观的欲望信号；另一层常被忽略，是给自己的心理暗示——一件让自己觉得"有魅力"的衣服会改变姿态、眼神与自我允许的程度，心理学称之为"穿衣认知"（enclothed cognition）。由此得出的选衣原则是：比"性感"更重要的是"自信"——不合身的紧身衣带来的局促，反而会抵消视觉效果。另外几点实用建议：把换装当作前戏的一部分仪式而非突然的"表演"；尺寸以舒适为前提；最重要的一条，衣着是可选项而非义务——任何"你必须穿给对方看"的要求，都已越过同意的边界。"""

C["b2997"] = r"""1981 年 6 月 5 日，美国疾控中心的《发病率与死亡率周报》报道了洛杉矶 5 例既往健康的年轻男同性恋者罹患肺孢子菌肺炎的病例——这是医学文献对艾滋病的首次记载。病毒本身于 1983--1984 年由法国巴斯德研究所的西诺西与蒙塔尼耶团队（后获 2008 年诺贝尔奖）和美国团队分别分离鉴定；1985 年血液筛查技术问世，输血传播自此被大幅阻断。这种疾病曾被称为 GRID（同性恋相关免疫缺陷），很快因其他人群同样受累而更名为 AIDS（获得性免疫缺陷综合征）。中国大陆首例报告见于 1985 年。从"绝症"到今天的慢性病管理，四十余年间医学的进步，正是从这则只有几百字的病例报道开始的。"""

C["b3021"] = r"""这块纪念布是"命名计划"（NAMES Project）的成果：1987 年由旧金山的活动家发起，每块布约一米见方，由逝者的亲友手工缝制，绣上姓名、照片与想说的话。它最终扩展为超过 4.8 万块、重约 54 吨的巨型织物，1996 年在华盛顿国家广场完整铺展时几乎望不到边。它的意义超越了哀悼：每一块布都是一名"不只是统计数字"的逝者，以可触摸的方式对抗当时"艾滋病只属于某类人、活该被忽视"的污名。红色丝带作为关怀 HIV 感染者的国际符号也诞生于同一时期的艺术家群体——从纪念布到红丝带，是哀悼转化为公共行动的典型轨迹。"""

C["b3057"] = r"""今天，"携带 HIV 生存"已经有了非常具体的图景：规范接受抗逆转录病毒治疗（ART）者，预期寿命已接近未感染者，多数服药方案为每日 1--3 片；治疗目标是将血液中病毒载量压到检测不到，此时感染者通过性行为传播病毒的风险为零（即 U=U，"检测不到=不传染"）。日常管理包括定期监测 CD4 细胞与病毒载量、按时服药以防耐药、接种建议的疫苗，以及关注血脂骨骼等长期健康。生活层面，感染不等于失去亲密与生育的权利：在病毒载量受控的前提下可以拥有无保护的性生活，孕产妇经规范阻断后母婴传播率可降至 1\% 以下。真正需要治疗的，还有围绕感染的社会性伤害——污名与自我孤立，这些同样有专业的心理与同伴支持资源可用。"""

C["b3349"] = r"""衣原体感染是全球最常见的细菌性性传播疾病，其最大的特点恰恰是"没感觉"——约 70\% 的女性与一半的男性感染后无明显症状，却可以悄然上行感染：女性可发展为盆腔炎、输卵管性不孕与异位妊娠，男性可引起附睾炎。诊断依靠尿液或拭子的核酸扩增检测，敏感度高；治疗以多西环素或阿奇霉素为主，强调性伴同时治疗、治疗期间禁欲，并在完成疗程后复查。因为它安静，常规筛查比等症状更有效：25 岁以下有性生活者建议每年筛查，新伴侣关系初期双方检测一次，是性价比最高的健康习惯。"""

C["b3517"] = r"""阴虱是专门寄生于阴毛区域的小型吸血虱（与头虱、体虱同属不同种），主要经亲密的皮肤与毛发接触传播，共用的毛巾、床品与衣物偶可成为媒介——这也是它与"卫生习惯差"无关、任何人都可能感染的道理。典型表现是阴部顽固瘙痒，内裤上可见铁锈色小点（虱的排泄物），皮肤上可出现特征性的淡蓝色斑，肉眼仔细观察能发现贴在毛干上的虱体与卵。治疗首选扑灭司林（氯菊酯）洗剂外用，一周后重复一次以杀灭新孵化的幼虫；剃毛并非必需但可加快清除；贴身衣物与床品需 60 摄氏度以上热水烫洗或密封放置两周。确诊阴虱还提醒医生与患者做一件事：同时筛查其他性传播疾病——经亲密接触传播的它，常常不是"独自前来"的。"""

C["b7639"] = r"""电子烟常被包装成传统香烟的"健康替代品"，但就性健康而言，这个承诺站不住脚。多数电子烟液含高浓度尼古丁，其血管收缩与损害血管内皮的作用机制与传统香烟相同——而勃起本质上是血管事件，内皮功能受损首当其冲。初步研究显示，使用电子烟者的血管功能指标下降程度并不明显优于吸烟者；尼古丁本身还与精子质量下降相关。此外，"加热不燃烧"产品同样释放尼古丁与气溶胶有害物；青少年群体中电子烟使用率上升，其对性腺尚在发育人群的长期影响尤其缺乏安全性数据。真正的结论是：不存在"安全的尼古丁"——最好的选择永远是不开始，已在使用者应当考虑彻底戒断而非换一种吸入方式。"""

